pub unsafe fn ZopfliCalculateEntropy(
    mut count: *const size_t,
    mut n: size_t,
    mut bitlengths: *mut c_double,
) {
    static mut kInvLog2: c_double = 1.4426950408889f64;
    let mut sum: c_uint = 0 as c_uint;
    let mut i: c_uint = 0;
    let mut log2sum: c_double = 0.;
